param([int]$BackendPort=8000,[int]$FrontendPort=5173)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;$script:checks=@();function Check($name,$url){$watch=[Diagnostics.Stopwatch]::StartNew();try{$r=Invoke-WebRequest $url -UseBasicParsing;$script:checks+=@{name=$name;url=$url;status=$r.StatusCode;bytes=$r.RawContentLength;ms=$watch.ElapsedMilliseconds;pass=($r.StatusCode -eq 200)}}catch{$script:checks+=@{name=$name;url=$url;status=0;bytes=0;ms=$watch.ElapsedMilliseconds;pass=$false;error=$_.Exception.Message}}}
Check 'health' "http://127.0.0.1:$BackendPort/api/health";Check 'presets' "http://127.0.0.1:$BackendPort/api/dashboard/demo-presets";Check 'frontend' "http://127.0.0.1:$FrontendPort/command-centre";$ids=@('6696d38f-5ced-4558-b1d9-d3508a3f58c1','ab258213-d6f7-44f0-867c-5d67f6edc508','be1916e0-931e-4b7f-ab80-03dde9a04092','f5df51e8-67cd-4572-82c6-c4555637d300','c79eccce-d9a6-49e3-9c58-72542420b6e2');foreach($id in $ids){Check "run-$id" "http://127.0.0.1:$BackendPort/api/orchestration/runs/$id";Check "json-$id" "http://127.0.0.1:$BackendPort/api/dashboard/export/$id`?format=json";Check "html-$id" "http://127.0.0.1:$BackendPort/api/dashboard/export/$id`?format=html"};$report=@{checks=$checks;passed=(@($checks|Where-Object pass).Count);failed=(@($checks|Where-Object {!$_.pass}).Count)};$report|ConvertTo-Json -Depth 5|Set-Content (Join-Path $root 'outputs\reports\demo_verification_report.json') -Encoding UTF8;$report|ConvertTo-Json -Depth 5;if($report.failed){exit 1}
